interface.signature:
GET /health/full
Response: {
  "status": "ok" | "degraded",
  "components": {
    "mcp_server": "ok" | "degraded" | "unavailable",
    "redis": "ok" | "unavailable",
    "llm_api": "ok" | "unavailable",
    "agentic_memories": {
      "status": "ok" | "degraded" | "unavailable",
      "checks": { "chroma": {"ok": true}, ... }
    },
    "proactive_worker": { "status": "ok" | "degraded" | "unavailable", "alive": bool },
    "langfuse": { "enabled": bool, "client_available": bool }
  },
  "timestamp": "2026-01-26T10:00:00Z"
}

interface HealthStatus {
  status: 'ok' | 'degraded';
  components: {
    mcp_server: ComponentStatus;
    redis: ComponentStatus;
    llm_api: ComponentStatus;
    agentic_memories: AgenticMemoriesStatus;
    proactive_worker: WorkerStatus;
    langfuse: LangfuseStatus;
  };
  timestamp: string;
}

type ComponentStatus = 'ok' | 'degraded' | 'unavailable';

interface AgenticMemoriesStatus {
  status: ComponentStatus;
  checks?: Record<string, { ok: boolean }>;
}

interface HealthState {
  health: {
    backend: ComponentStatus;
    mcp: ComponentStatus;
    redis: ComponentStatus;
    memories: ComponentStatus;
  };
  activeLLM: string;
  updateHealth: (health: HealthState['health']) => void;
  setActiveLLM: (llm: string) => void;
}
